#!/bin/bash
# Uninstall script for Phoenix Code
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Phoenix Code..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Phoenix Code if running..."
pkill -f "Phoenix Code" 2>/dev/null || true

# Remove /Applications/Phoenix Code.app
echo "Removing /Applications/Phoenix Code.app..."
if [ -d "/Applications/Phoenix Code.app" ]; then
    rm -rf "/Applications/Phoenix Code.app" 2>/dev/null || true
elif [ -f "/Applications/Phoenix Code.app" ]; then
    rm -f "/Applications/Phoenix Code.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/io.phcode
echo "Removing $HOME/Library/Application Support/io.phcode..."
if [ -d "$HOME/Library/Application Support/io.phcode" ]; then
    rm -rf "$HOME/Library/Application Support/io.phcode" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/io.phcode" ]; then
    rm -f "$HOME/Library/Application Support/io.phcode" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/io.phcode
echo "Removing $HOME/Library/Caches/io.phcode..."
if [ -d "$HOME/Library/Caches/io.phcode" ]; then
    rm -rf "$HOME/Library/Caches/io.phcode" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/io.phcode" ]; then
