fi

# Remove $HOME/Library/Saved Application State/io.phcode.savedState
echo "Removing $HOME/Library/Saved Application State/io.phcode.savedState..."
if [ -d "$HOME/Library/Saved Application State/io.phcode.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/io.phcode.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/io.phcode.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/io.phcode.savedState" 2>/dev/null || true
fi

# Remove $HOME/Library/WebKit/io.phcode
echo "Removing $HOME/Library/WebKit/io.phcode..."
if [ -d "$HOME/Library/WebKit/io.phcode" ]; then
    rm -rf "$HOME/Library/WebKit/io.phcode" 2>/dev/null || true
elif [ -f "$HOME/Library/WebKit/io.phcode" ]; then
    rm -f "$HOME/Library/WebKit/io.phcode" 2>/dev/null || true
fi

# Remove $HOME/Documents/Phoenix Code
echo "Removing $HOME/Documents/Phoenix Code..."
if [ -d "$HOME/Documents/Phoenix Code" ]; then
    rm -rf "$HOME/Documents/Phoenix Code" 2>/dev/null || true
elif [ -f "$HOME/Documents/Phoenix Code" ]; then
    rm -f "$HOME/Documents/Phoenix Code" 2>/dev/null || true
fi

